from heirs_data import add, key, tex
from heirs_xml import Def, T

FB = "Items/HE_Books.xml"
F = "Chains/HE_Chains35.xml"
FI = "Chains/HE_ChainItems35.xml"
OPEN = {"texPath": "Things/Item/Book/Novel/Novel_Open", "graphicClass": "Graphic_Multi", "drawSize": 0.7}
VERTICAL = {"texPath": "Things/Item/Book/Novel/Novel_Vertical", "graphicClass": "Graphic_Multi", "addTopAltitudeBias": True}

add(FB, Def("RulePackDef", "HE_BookNamer", rulePack={"rulesStrings": ["title->[heirs_title]"]}),
    Def("RulePackDef", "HE_BookDescriber", rulePack={"rulesStrings": ["desc->[heirs_desc]"]}))

key("HE_BookBenefit", "{0} culture knowledge: {1} per hour of reading, up to {2}", "{0} kültür bilgisi: okuma saati başına {1}, en fazla {2}")
key("HE_BookLearned", "your colony already knows all this book can teach", "kolonin bu kitabın öğretebileceği her şeyi zaten biliyor")


def book(nation, name, en, tr, den, dtr, form, color, emblem, per_hour, cap, value, epic=False):
    """A book of a nation. Its title and blurb are its own (keyed, so they translate); reading teaches the nation's knowledge."""
    d = f"HE_Book_{nation}_{name}"
    key(f"{d}_Title", en, tr)
    key(f"{d}_Desc", den, dtr)
    fields = dict(
        label=T(en, tr),
        description=T(den, dtr),
        graphicData={"texPath": f"HeirsOfEarth/Items/Books/{d}", "graphicClass": "Graphic_Single", "drawSize": 0.8},
        uiIconPath=f"HeirsOfEarth/Items/Books/{d}",
        statBases={"MarketValue": value, "Beauty": 6 if epic else 2},
        comps=[{"@Class": "CompProperties_Book", "nameMaker": "HE_BookNamer", "descriptionMaker": "HE_BookDescriber",
                "ageYearsRange": "40~400", "openGraphic": OPEN, "verticalGraphic": VERTICAL,
                "doers": [{"@Class": "HeirsOfEarth.BookOutcomeProperties_HeirsKnowledge", "nation": f"HE_{nation}", "perHour": per_hour,
                           "cap": cap, "titleKey": f"{d}_Title", "descKey": f"{d}_Desc"},
                          {"@Class": "BookOutcomeProperties_JoyFactorModifier"}]}],
    )
    if epic:
        fields.update(tradeability="None", thingSetMakerTags={"@Inherit": "False", "#items": []},
                      statBases={"MarketValue": value, "Beauty": 6, "DeteriorationRate": 0, "MaxHitPoints": 160, "Flammability": 0.4})
    else:
        fields["tradeTags"] = [f"HE_Books_{nation}"]
    add(FB, Def("ThingDef", d, parent="BookBase", **fields))
    tex(f"HeirsOfEarth/Items/Books/{d}", "heirs_book", form=form, color=color, emblem=emblem, seed=1700 + len(d) * 7 + int(per_hour * 10))
    return d


