for s in SAGAS:
    n = s["nation"]
    epic = book(n, *s["book"], s["form"], s["color"], s["emblem"], 1.5, 300, 2500, epic=True)
    rname, ren, rtr, rden, rdtr = s["relic"]
    relic = item(f"HE_{n}_{rname}", ren, rtr, rden, rdtr, "heirs_book", 1200, 2, f"HE_{n}",
                 pargs={"form": s["form"], "color": s["color"], "emblem": s["emblem"], "worn": True, "seed": 1750 + len(rname)}, beauty=8)
    d_things, d_en, d_tr, d_ten, d_ttr, d_den, d_dtr = s["deliver"]
    b_def, b_en, b_tr, b_ten, b_ttr, b_den, b_dtr = s["build"]
    r_def, r_en, r_tr, r_ten, r_ttr, r_den, r_dtr = s["research"]
    st_en, st_tr, st_ten, st_ttr, st_den, st_dtr, layout, wall, prop, enemy = s["site"]
    keep_en, keep_tr, keep_ten, keep_ttr, own_en, own_tr, own_ten, own_ttr = s["choice"]
    add(F, Def("HeirsOfEarth.ChainDef", f"HE_Saga_{n}", nation=f"HE_{n}", after=f"HE_Chain_{n}", artifact=epic, startKnowledge=120,
               label=T(*s["label"]), description=T(*s["desc"]), startText=T(*s["start"]), endText=T(*s["end"]),
               steps=[
                   step("Deliver", d_en, d_tr, d_ten, d_ttr, d_den, d_dtr, things=things(**d_things)),
                   step("Build", b_en, b_tr, b_ten, b_ttr, b_den, b_dtr, building=b_def),
                   step("Research", r_en, r_tr, r_ten, r_ttr, r_den, r_dtr, project=r_def),
                   step("Site", st_en, st_tr, st_ten, st_ttr, st_den, st_dtr, enemy=enemy,
                        siteLayout=layout, siteWall=wall, siteProp=prop, siteReward=relic, siteThreat=1.3),
                   step("Choice", "The fate of the original", "Aslın kaderi",
                        "Your scribes have made a fair copy. Now the original must go somewhere.",
                        "Kâtiplerin temiz bir kopya çıkardı. Şimdi aslının bir yere gitmesi gerekiyor.",
                        options=[
                            option(keep_en, keep_tr, keep_ten, keep_ttr, goodwill=30, knowledge=40, keep=True, rewards=things(Silver=500),
                                   takes={relic: 1}),
                            option(own_en, own_tr, own_ten, own_ttr, goodwill=-15, keep=True),
                        ]),
               ]))

